  "implementation": "def solve(case):
    threshold = case['threshold']
    calls = case['calls']
    accepted_call_ids = []
    diagnostics = []
    for call in calls:
        diff = call['loss_without_call'] - call['loss_with_call']
        normalized_gain = diff / call['prediction_tokens']
        if call['parseable'] and normalized_gain >= threshold:
            accepted = True
            accepted_call_ids.append(call['call_id'])
        else:
            accepted = False
        diagnostics.append({
            'accepted': accepted,
            'call_id': call['call_id'],
            'normalized_gain': normalized_gain
        })
    return {
        'accepted_call_ids': accepted_call_ids,
        'diagnostics': diagnostics
    }"
}
